export function isEventPayload(family: string | undefined, type: string | undefined, v: unknown): v is EventPayload {
  if (family === "worktree" && type === "kept") return isWorktreeEvent(v)
  if (family === "hook" && type === "started") return isHookEvent(v)
  if (family === "hook" && type === "result") return isHookEvent(v)
  if (family === "issue" && type === "filed") return isIssueEvent(v)
  if (family === "issue" && type === "updated") return isIssueEvent(v)
  if (family === "issue" && type === "closed") return isIssueEvent(v)
  if (family === "goal" && type === "added") return isGoalEvent(v)
  if (family === "goal" && type === "edited") return isGoalEvent(v)
  if (family === "goal" && type === "amended") return isGoalEvent(v)
  if (family === "goal" && type === "finished") return isGoalEvent(v)
  if (family === "goal" && type === "dropped") return isGoalEvent(v)
  if (family === "checkin" && type === "summary") return isCheckinEvent(v)
  if (family === "ci-health" && type === "slow-test") return isSlowTestEvent(v)
  if (family === "rule" && type === "changed") return isRuleEvent(v)
  if (family === "merge" && type === "queued") return isMergeEvent(v)
  if (family === "merge" && type === "trial") return isMergeEvent(v)
  if (family === "merge" && type === "checks") return isMergeEvent(v)
  if (family === "merge" && type === "landed") return isMergeEvent(v)
  if (family === "merge" && type === "failed") return isMergeEvent(v)
  if (family === "merge" && type === "returned") return isMergeEvent(v)
  if (family === "merge" && type === "conflict") return isMergeEvent(v)
  if (family === "merge" && type === "rolled-back") return isMergeEvent(v)
  if (family === "merge" && type === "decision") return isMergeDecisionEvent(v)
  if (family === "merge" && type === "fix-requested") return isMergeEvent(v)
  if (family === "machine" && type === "low-disk") return isMachineEvent(v)
  if (family === "machine" && type === "cache-repaired") return isMachineCacheEvent(v)
  if (family === "call" && type === "joined") return isCallEvent(v)
  if (family === "call" && type === "declined") return isCallEvent(v)
  if (family === "call" && type === "withdrawn") return isCallEvent(v)
  if (family === "review" && type === "result") return isReviewEvent(v)
  if (family === "pr" && type === "opened") return isPREvent(v)
  if (family === "pr" && type === "ready") return isPREvent(v)
  if (family === "pr" && type === "approved") return isPREvent(v)
  if (family === "pr" && type === "changes") return isPREvent(v)
  if (family === "pr" && type === "ci-failed") return isPREvent(v)
  if (family === "pr" && type === "ci-paused") return isPREvent(v)
  if (family === "pr" && type === "ci-passed") return isPREvent(v)
  if (family === "pr" && type === "returned") return isPREvent(v)
  if (family === "pr" && type === "merged") return isPREvent(v)
  if (family === "pr" && type === "closed") return isPREvent(v)
  if (family === "pr" && type === "comment") return isPREvent(v)
  if (family === "pr" && type === "held-comment") return isPREvent(v)
  if (family === "pr" && type === "review-assigned") return isPREvent(v)
  if (family === "pr" && type === "update") return isPREvent(v)
  if (family === "session" && type === "renamed") return isSessionEvent(v)
  if (family === "session" && type === "promoted") return isSessionEvent(v)
  if (family === "session" && type === "adopted") return isSessionEvent(v)
  if (family === "session" && type === "account") return isSessionEvent(v)
  if (family === "session" && type === "instructions") return isSessionEvent(v)
  if (family === "session" && type === "instruction-batch") return isInstructionBatchEvent(v)
  if (family === "session" && type === "seat") return isSessionEvent(v)
  if (family === "session" && type === "spawned") return isSessionEvent(v)
  if (family === "session" && type === "transfer-request") return isSessionEvent(v)
  if (family === "alert" && type === "doctor") return isAlertEvent(v)
  if (family === "alert" && type === "engine") return isAlertEvent(v)
  if (family === "service" && type === "failed") return isServiceFailedEvent(v)
  if (family === "service" && type === "helper-outcome") return isHelperOutcomeEvent(v)
  if (family === "engine" && type === "root-flush") return isEngineEvent(v)
  if (family === "question" && type === "withdrawn") return isQuestionEvent(v)
  if (family === "shell" && type === "result") return isShellEvent(v)
  if (family === "run" && type === "result") return isRunEvent(v)
  if (family === "turn" && type === "completed") return isTurnEvent(v)
  if (family === "turn" && type === "failed") return isTurnEvent(v)
  if (family === "turn" && type === "stopped") return isTurnEvent(v)
  return false
}

function isRecord(v: unknown): v is Record<string, unknown> {
  return typeof v === "object" && v !== null && !Array.isArray(v)
}

function isStringList(v: unknown): v is string[] {
  return Array.isArray(v) && v.every((item: unknown) => typeof item === "string")
}
function isNumberList(v: unknown): v is number[] {
  return Array.isArray(v) && v.every((item: unknown) => Number.isInteger(item))
}
